"use client";

import React, { useState, useEffect } from "react";
import { motion } from "framer-motion";
import WidgetCard from "../ui/WidgetCard";

const ProgressTimelineWidget = ({ milestones }) => {
  const [activeIndex, setActiveIndex] = useState(null);
  const [isLoaded, setIsLoaded] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => {
      setIsLoaded(true);
    }, 300);

    return () => clearTimeout(timer);
  }, []);

  // Animation variants
  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.1,
        delayChildren: 0.3
      }
    }
  };

  const itemVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: { opacity: 1, y: 0 }
  };

  const pulseVariants = {
    pulse: {
      scale: [1, 1.1, 1],
      opacity: [0.7, 1, 0.7],
      transition: {
        duration: 2,
        repeat: Infinity,
        repeatType: "loop"
      }
    }
  };

  const glowVariants = {
    glow: {
      boxShadow: [
        "0 0 5px rgba(76, 109, 255, 0.5)",
        "0 0 15px rgba(76, 109, 255, 0.7)",
        "0 0 5px rgba(76, 109, 255, 0.5)"
      ],
      transition: {
        duration: 2,
        repeat: Infinity,
        repeatType: "loop"
      }
    }
  };

  return (
    <WidgetCard
      title="Your Speaking Journey"
      theme="blue"
      action={
        <div className="flex items-center">
          <span className="text-sm text-blue-400">Progress: {milestones[milestones.length - 1].progress}%</span>
        </div>
      }
      fullHeight
    >
      <motion.div
        className="relative"
        variants={containerVariants}
        initial="hidden"
        animate={isLoaded ? "visible" : "hidden"}
      >
        {/* Timeline line */}
        <div className="absolute left-4 top-0 bottom-0 w-0.5 bg-gradient-to-b from-blue-500/30 via-purple-500/30 to-blue-500/30 rounded-full" />

        {/* Timeline items */}
        <div className="space-y-6 relative">
          {milestones.map((milestone, index) => {
            const isActive = activeIndex === index;
            const isCompleted = milestone.completed;
            const isCurrent = milestone.current;

            return (
              <motion.div
                key={milestone.id}
                className="relative pl-12"
                variants={itemVariants}
                onMouseEnter={() => setActiveIndex(index)}
                onMouseLeave={() => setActiveIndex(null)}
              >
                {/* Timeline dot */}
                <motion.div
                  className={`absolute left-2 top-1.5 w-5 h-5 rounded-full border-2 transform -translate-x-1/2 ${
                    isCompleted
                      ? "bg-blue-500 border-blue-300"
                      : isCurrent
                      ? "bg-purple-500 border-purple-300"
                      : "bg-gray-700 border-gray-600"
                  }`}
                  variants={isCompleted || isCurrent ? pulseVariants : {}}
                  animate={isCompleted || isCurrent ? "pulse" : ""}
                >
                  {isCompleted && (
                    <motion.div
                      className="absolute inset-0 rounded-full bg-blue-400"
                      initial={{ scale: 0 }}
                      animate={{ scale: 1 }}
                      transition={{ duration: 0.3 }}
                    >
                      <svg
                        xmlns="http://www.w3.org/2000/svg"
                        className="h-full w-full text-blue-900 p-0.5"
                        viewBox="0 0 20 20"
                        fill="currentColor"
                      >
                        <path
                          fillRule="evenodd"
                          d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z"
                          clipRule="evenodd"
                        />
                      </svg>
                    </motion.div>
                  )}
                </motion.div>

                {/* Content */}
                <motion.div
                  className={`p-4 rounded-lg transition-all duration-300 ${
                    isActive || isCurrent
                      ? "bg-gradient-to-r from-blue-900/30 to-purple-900/20 border border-blue-500/30"
                      : "bg-gray-800/30 border border-gray-700/50"
                  }`}
                  variants={isCurrent ? glowVariants : {}}
                  animate={isCurrent ? "glow" : ""}
                  whileHover={{ 
                    y: -5, 
                    transition: { duration: 0.2 } 
                  }}
                >
                  <div className="flex justify-between items-start mb-2">
                    <h3 className="text-base font-medium text-blue-300 dashboard-card-title">
                      {milestone.title}
                    </h3>
                    <div className="flex items-center">
                      <span
                        className={`text-xs px-2 py-1 rounded-full ${
                          isCompleted
                            ? "bg-blue-900/50 text-blue-300"
                            : isCurrent
                            ? "bg-purple-900/50 text-purple-300"
                            : "bg-gray-800 text-gray-400"
                        }`}
                      >
                        {isCompleted ? "Completed" : isCurrent ? "Current" : "Upcoming"}
                      </span>
                    </div>
                  </div>

                  <p className="text-sm text-gray-300 mb-3">{milestone.description}</p>

                  {/* Progress indicators */}
                  {(isCompleted || isCurrent) && (
                    <div className="mt-2">
                      <div className="flex justify-between text-xs mb-1">
                        <span className="text-gray-400">Progress</span>
                        <span className="text-blue-400">{milestone.progress}%</span>
                      </div>
                      <div className="h-1.5 w-full bg-gray-800 rounded-full overflow-hidden">
                        <motion.div
                          className="h-full bg-gradient-to-r from-blue-500 to-purple-500 rounded-full"
                          initial={{ width: 0 }}
                          animate={{ width: `${milestone.progress}%` }}
                          transition={{ duration: 1, delay: 0.5 }}
                        />
                      </div>
                    </div>
                  )}

                  {/* Achievement badges */}
                  {milestone.achievements && milestone.achievements.length > 0 && (
                    <div className="mt-3 flex flex-wrap gap-2">
                      {milestone.achievements.map((achievement, i) => (
                        <motion.div
                          key={i}
                          className="flex items-center bg-blue-900/20 border border-blue-500/20 rounded-full px-2 py-1"
                          initial={{ opacity: 0, scale: 0.8 }}
                          animate={{ opacity: 1, scale: 1 }}
                          transition={{ delay: 0.7 + (i * 0.1) }}
                          whileHover={{ scale: 1.05 }}
                        >
                          <div className="w-3 h-3 rounded-full bg-blue-500 mr-1.5" />
                          <span className="text-xs text-blue-300">{achievement}</span>
                        </motion.div>
                      ))}
                    </div>
                  )}
                </motion.div>
              </motion.div>
            );
          })}
        </div>
      </motion.div>
    </WidgetCard>
  );
};

export default ProgressTimelineWidget;
